 private List<Uri> received()throws Exception {ArrayList<Uri> found=new ArrayList<>();if(Build.VERSION.SDK_INT>=29){try(Cursor cursor=c.getContentResolver().query(MediaStore.Downloads.EXTERNAL_CONTENT_URI,new String[]{"_id","_display_name","relative_path","is_pending"},"_display_name LIKE ?",new String[]{prefix+"%"},null)){while(cursor!=null&&cursor.moveToNext())if(!cursor.getString(2).contains("ToTV-test-sources")&&cursor.getInt(3)==0)found.add(ContentUris.withAppendedId(MediaStore.Downloads.EXTERNAL_CONTENT_URI,cursor.getLong(0)));}}else{File dir=Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS);File[] fs=dir.listFiles();if(fs!=null)for(File f:fs)if(f.getName().startsWith(prefix))found.add(Uri.fromFile(f));}return found;}
